.darma-loader-darma-b12-barber-pole .darma-loader-darma-b12-barber-pole__pole::after { content: ''; position: absolute; left: -30%; top: -100%; width: 160%; height: 300%; background: repeating-linear-gradient(45deg, var(--accent) 0 calc(var(--loader-size, 116px) * .04), transparent calc(var(--loader-size, 116px) * .04) calc(var(--loader-size, 116px) * .08), var(--accent-2) calc(var(--loader-size, 116px) * .08) calc(var(--loader-size, 116px) * .12), transparent calc(var(--loader-size, 116px) * .12) calc(var(--loader-size, 116px) * .16)); animation: darma-loader-darma-b12-barber-pole-barber calc(var(--loader-speed, 1s) * 1.6) linear infinite; }
